mapper.update:
UPDATE ai_memory_outbox o JOIN ai_memory_deletion_job j ON j.tenant_id=o.tenant_id AND j.id=o.event_id AND j.item_id=o.aggregate_id AND j.deletion_epoch=o.deletion_epoch
SET o.status='CLAIMED',o.revision=o.revision+1,o.attempts=o.attempts+1,o.lease_until=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 60 SECOND),o.receipt_ref=#{token}
WHERE o.tenant_id=#{delivery.tenantId} AND o.event_id=#{delivery.eventId} AND o.deletion_epoch=#{delivery.deletionEpoch} AND o.revision=#{delivery.revision}
AND o.status IN ('QUEUED','CLAIMED','BLOCKED') AND o.attempts<8 AND (o.lease_until IS NULL OR o.lease_until<=UTC_TIMESTAMP(6))
AND j.status IN ('QUEUED','RUNNING','BLOCKED','RETRYABLE_FAILED') AND j.attempts<8 AND j.deadline>UTC_TIMESTAMP(6)

UPDATE ai_memory_outbox SET status='BLOCKED',revision=revision+1,receipt_ref=NULL,lease_until=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 60 SECOND)
WHERE tenant_id=#{delivery.tenantId} AND event_id=#{delivery.eventId} AND deletion_epoch=#{delivery.deletionEpoch}
AND status='CLAIMED' AND revision=#{delivery.revision}+1 AND receipt_ref=#{token}
